// Open data behind /translation-progress/ and /data/fhb-languages.{json,csv} (unit 2nh, 2026-11-10).
// ONE row per language of the 80-language roster, derived at BUILD time from the same files the
// rest of the site already reads — nothing here is typed per language and no count is typed:
//   roster        src/data/language-roster.json  (the 80-language commitment, generated by fhb-chain.py)
//   read online   src/data/reader-languages.json (languages live:true in the /read reader, generated)
//   print edition src/data/edition-registry.json (editions whose Ingram files are submitted, generated)
// Script comes from the endonym's own Unicode script (CJK and Hangul are named by hand: the
// Unicode name says only "CJK"). No per-language launch date is recorded in any of these files,
// so none is published.
import { execFileSync } from 'node:child_process';
import registry from '../data/edition-registry.json' with { type: 'json' };
import roster from '../data/language-roster.json' with { type: 'json' };
import readerLanguages from '../data/reader-languages.json' with { type: 'json' };

export const SITE_URL = 'https://fathersheartbible.com';
export const PAGE_URL = `${SITE_URL}/translation-progress/`;
export const JSON_URL = `${SITE_URL}/data/fhb-languages.json`;
export const CSV_URL = `${SITE_URL}/data/fhb-languages.csv`;

export interface LanguageRow {
	code: string;
	name: string;
	native_name: string;
	script: string;
	region: string;
	read_online: boolean;
	print_edition: boolean;
	status: 'read online and in print' | 'read online' | 'print edition' | 'in preparation';
	read_url: string | null;
}

const SCRIPT_NAMES: Record<string, string> = {
	LATIN: 'Latin',
	ETHIOPIC: 'Ethiopic',
	ARABIC: 'Arabic',
	BENGALI: 'Bengali',
	GREEK: 'Greek',
	GUJARATI: 'Gujarati',
	DEVANAGARI: 'Devanagari',
	KANNADA: 'Kannada',
	MALAYALAM: 'Malayalam',
	MYANMAR: 'Myanmar',
	ORIYA: 'Odia',
	GURMUKHI: 'Gurmukhi',
	TAMIL: 'Tamil',
	TELUGU: 'Telugu',
	THAI: 'Thai',
	CYRILLIC: 'Cyrillic',
	HANGUL: 'Hangul',
};
// Unicode names these only "CJK"; the roster code says which Chinese or Japanese script.
const CJK_BY_CODE: Record<string, string> = {
	ja: 'Japanese (Han, Hiragana, Katakana)',
	yue: 'Han (Traditional)',
	'zh-hant': 'Han (Traditional)',
	'zh-hans': 'Han (Simplified)',
};

function scriptOf(code: string, text: string): string {
	if (CJK_BY_CODE[code]) return CJK_BY_CODE[code];
	const tally = new Map<string, number>();
	for (const ch of text) {
		if (!/\p{L}/u.test(ch)) continue;
		const key = ch.codePointAt(0)! <= 0x24f ? 'LATIN' : null; // basic + extended Latin
		const name = key ?? scriptByRange(ch.codePointAt(0)!);
		tally.set(name, (tally.get(name) ?? 0) + 1);
	}
	const top = [...tally.entries()].sort((a, b) => b[1] - a[1])[0]?.[0] ?? 'LATIN';
	return SCRIPT_NAMES[top] ?? top;
}

function scriptByRange(cp: number): string {
	if (cp >= 0x1200 && cp <= 0x139f) return 'ETHIOPIC';
	if (cp >= 0x600 && cp <= 0x77f) return 'ARABIC';
	if (cp >= 0x980 && cp <= 0x9ff) return 'BENGALI';
	if (cp >= 0x370 && cp <= 0x3ff) return 'GREEK';
	if (cp >= 0xa80 && cp <= 0xaff) return 'GUJARATI';
	if (cp >= 0x900 && cp <= 0x97f) return 'DEVANAGARI';
	if (cp >= 0xc80 && cp <= 0xcff) return 'KANNADA';
	if (cp >= 0xd00 && cp <= 0xd7f) return 'MALAYALAM';
	if (cp >= 0x1000 && cp <= 0x109f) return 'MYANMAR';
	if (cp >= 0xb00 && cp <= 0xb7f) return 'ORIYA';
	if (cp >= 0xa00 && cp <= 0xa7f) return 'GURMUKHI';
	if (cp >= 0xb80 && cp <= 0xbff) return 'TAMIL';
	if (cp >= 0xc00 && cp <= 0xc7f) return 'TELUGU';
	if (cp >= 0xe00 && cp <= 0xe7f) return 'THAI';
	if (cp >= 0x400 && cp <= 0x52f) return 'CYRILLIC';
	if (cp >= 0xac00 && cp <= 0xd7af) return 'HANGUL';
	if (cp >= 0x1e00 && cp <= 0x1eff) return 'LATIN';
	return 'OTHER';
}

const regionLabel = new Map(
	(roster.regions as { key: string; label: string }[]).map((r) => [r.key, r.label]),
);
const live = new Set((readerLanguages.languages as { code: string }[]).map((l) => l.code));
const printed = new Set(
	(registry.editions as { code: string; soon?: boolean }[])
		.filter((e) => !e.soon)
		.map((e) => e.code),
);

export const rows: LanguageRow[] = (
	roster.languages as { code: string; english: string; endonym?: string; region: string }[]
)
	.map((l): LanguageRow => {
		const read = live.has(l.code);
		// English is the source text and is in print (the /print catalogue); the registry lists the language editions only.
		const print = l.code === 'en' || printed.has(l.code);
		const native = l.endonym ?? l.english;
		return {
			code: l.code,
			name: l.english,
			native_name: native,
			script: scriptOf(l.code, native),
			region: regionLabel.get(l.region) ?? l.region,
			read_online: read,
			print_edition: print,
			status:
				read && print
					? 'read online and in print'
					: read
						? 'read online'
						: print
							? 'print edition'
							: 'in preparation',
			read_url: read
				? l.code === 'en'
					? `${SITE_URL}/read/`
					: `${SITE_URL}/read/${l.code}/`
				: null,
		};
	})
	.sort((a, b) => (a.code === 'en' ? -1 : b.code === 'en' ? 1 : a.name.localeCompare(b.name)));

export const counts = {
	roster: rows.length,
	readOnline: rows.filter((r) => r.read_online).length,
	printEditions: rows.filter((r) => r.print_edition).length,
	both: rows.filter((r) => r.read_online && r.print_edition).length,
	inPreparation: rows.filter((r) => r.status === 'in preparation').length,
	scripts: new Set(rows.map((r) => r.script)).size,
};

/** Newest git commit date of the three source files (build-time; no git = today, never invented). */
export const dateModified: string = (() => {
	try {
		const out = execFileSync(
			'git',
			[
				'log',
				'-1',
				'--format=%cI',
				'--',
				'src/data/language-roster.json',
				'src/data/reader-languages.json',
				'src/data/edition-registry.json',
			],
			{ encoding: 'utf8' },
		).trim();
		if (out) return out.slice(0, 10);
	} catch {
		/* fall through */
	}
	return new Date().toISOString().slice(0, 10);
})();

const q = (s: string | boolean | null) => {
	const v = s === null ? '' : String(s);
	return /[",\n]/.test(v) ? `"${v.replace(/"/g, '""')}"` : v;
};
export const CSV_COLUMNS = [
	'code',
	'name',
	'native_name',
	'script',
	'region',
	'status',
	'read_online',
	'print_edition',
	'read_url',
] as const;
export const toCsv = () =>
	[CSV_COLUMNS.join(','), ...rows.map((r) => CSV_COLUMNS.map((c) => q(r[c])).join(','))].join(
		'\n',
	) + '\n';
